// WorkerGPUConfig defines GPU allocation for a worker.
type WorkerGPUConfig struct {
	GPUs []any `json:"gpus" yaml:"gpus"`
}

// GPUIndexes returns entries that are integer indexes.
func (c WorkerGPUConfig) GPUIndexes() []int {
	var out []int
	for _, g := range c.GPUs {
		switch v := g.(type) {
		case int:
			out = append(out, v)
		case float64:
			out = append(out, int(v))
		}
	}
	return out
}

// GPUIDs returns entries that are string GPU IDs.
func (c WorkerGPUConfig) GPUIDs() []string {
	var out []string
	for _, g := range c.GPUs {
		if v, ok := g.(string); ok {
			out = append(out, v)
		}
	}
	return out
}

