// TaskStatus represents the state of a task in its lifecycle.
type TaskStatus int

func (v TaskStatus) Value() (driver.Value, error) {
	return int64(v), nil
}

func (ts TaskStatus) StatusOrder() int {
	switch ts {
	case TaskStatusReceived:
		return 10
	case TaskStatusQueued:
		return 20
	case TaskStatusDispatched:
		return 30
	case TaskStatusPreparing:
		return 40
	case TaskStatusServing:
		return 50
	case TaskStatusSettingUp:
		return 60
	case TaskStatusRunning:
		return 70
	case TaskStatusCancelling:
		return 80
	case TaskStatusUploading:
		return 90
	case TaskStatusCompleted, TaskStatusFailed, TaskStatusCancelled:
		return 100
	default:
		return 0
	}
}

func (ts TaskStatus) String() string {
	switch ts {
	case TaskStatusReceived:
		return "received"
	case TaskStatusQueued:
		return "queued"
	case TaskStatusDispatched:
		return "dispatched"
	case TaskStatusPreparing:
		return "preparing"
	case TaskStatusServing:
		return "serving"
	case TaskStatusSettingUp:
		return "setting_up"
	case TaskStatusRunning:
		return "running"
	case TaskStatusCancelling:
		return "cancelling"
	case TaskStatusUploading:
		return "uploading"
	case TaskStatusCompleted:
		return "completed"
	case TaskStatusFailed:
		return "failed"
	case TaskStatusCancelled:
		return "cancelled"
	default:
		return "unknown"
	}
}

// Parse converts a string status name to a TaskStatus.
func (TaskStatus) Parse(s string) (TaskStatus, bool) {
	for i := TaskStatus(0); i <= TaskStatusCancelled; i++ {
		if i.String() == s {
			return i, true
		}
	}
	return TaskStatusUnknown, false
}

func (ts TaskStatus) IsTerminal() bool {
	return ts == TaskStatusCompleted || ts == TaskStatusFailed || ts == TaskStatusCancelled
}

func (ts TaskStatus) IsQueued() bool {
	return ts == TaskStatusReceived || ts == TaskStatusQueued
}

func (ts TaskStatus) IsInProgress() bool {
	return ts == TaskStatusDispatched || ts == TaskStatusPreparing || ts == TaskStatusServing || ts == TaskStatusSettingUp || ts == TaskStatusRunning || ts == TaskStatusCancelling || ts == TaskStatusUploading
}

func (ts TaskStatus) IsCancelling() bool {
	return ts == TaskStatusCancelling
}

func (ts TaskStatus) CanTransitionTo(next TaskStatus) bool {
	if ts.IsTerminal() {
		return false
	}
	if next.IsTerminal() || next == TaskStatusCancelling {
		return ts != next
	}
	if ts == TaskStatusUnknown {
		return true
	}
	if ts.StatusOrder() <= next.StatusOrder() {
		return true
	}
	if ts == TaskStatusDispatched && (next == TaskStatusReceived || next == TaskStatusQueued) {
		return true
	}
	return false
}

const (
	TaskStatusUnknown TaskStatus = iota
	TaskStatusReceived
	TaskStatusQueued
	TaskStatusDispatched
	TaskStatusPreparing
	TaskStatusServing
	TaskStatusSettingUp
	TaskStatusRunning
	TaskStatusCancelling
	TaskStatusUploading
	TaskStatusCompleted
	TaskStatusFailed
	TaskStatusCancelled
)

